class SmoothScroll{constructor(){this.ease=0.1;this.elements=new Set();this.onWheel=this.onWheel.bind(this);this.animate=this.animate.bind(this);this.observe();this.init();this.animate()}observe(){new MutationObserver(mutations=>{mutations.forEach(m=>{m.addedNodes.forEach(n=>{if(n.nodeType===1){this.addIfScrollable(n);n.querySelectorAll("*").forEach(el=>this.addIfScrollable(el))}})})}).observe(document.body,{childList:true,subtree:true})}init(){this.elements.clear();[...document.querySelectorAll("*")].forEach(el=>this.addIfScrollable(el));this.addIfScrollable(window)}addIfScrollable(el){const style=getComputedStyle(el);const vertScroll=el.scrollHeight>el.clientHeight&&(style.overflowY==="auto"||style.overflowY==="scroll");const horScroll=el.scrollWidth>el.clientWidth&&(style.overflowX==="auto"||style.overflowX==="scroll");if((vertScroll||horScroll)&&!this.elements.has(el)){this.elements.add(el);el._targetY=el.scrollTop||0;el._targetX=el.scrollLeft||0;el.addEventListener("wheel",e=>this.onWheel(e,el),{passive:false})}else if((el===window||el===document.body||el===document.documentElement)&&!this.elements.has(window)){this.elements.add(window);window._targetY=window.scrollY||0;window._targetX=window.scrollX||0;window.addEventListener("wheel",e=>this.onWheel(e,window),{passive:false})}}onWheel(e,el){const deltaY=e.deltaY;const deltaX=e.deltaX;if(el===window){const maxY=document.documentElement.scrollHeight-window.innerHeight;const maxX=document.documentElement.scrollWidth-window.innerWidth;window._targetY=Math.min(Math.max(window._targetY+deltaY,0),maxY);window._targetX=Math.min(Math.max(window._targetX+deltaX,0),maxX)}else{const maxY=el.scrollHeight-el.clientHeight;const maxX=el.scrollWidth-el.clientWidth;el._targetY=Math.min(Math.max(el._targetY+deltaY,0),maxY);el._targetX=Math.min(Math.max(el._targetX+deltaX,0),maxX)}e.preventDefault()}animate(){this.elements.forEach(el=>{if(el===window){const curY=window.scrollY;const curX=window.scrollX;const dy=window._targetY-curY;const dx=window._targetX-curX;if(Math.abs(dy)>0.5||Math.abs(dx)>0.5){window.scrollTo(curX+dx*this.ease,curY+dy*this.ease)}else{window.scrollTo(window._targetX,window._targetY)}}else{const curY=el.scrollTop;const curX=el.scrollLeft;const dy=el._targetY-curY;const dx=el._targetX-curX;if(Math.abs(dy)>0.5||Math.abs(dx)>0.5){el.scrollTop=curY+dy*this.ease;el.scrollLeft=curX+dx*this.ease}else{el.scrollTop=el._targetY;el.scrollLeft=el._targetX}}});requestAnimationFrame(this.animate)}}
new SmoothScroll();
